def evaluate_rpn_safe(tokens: List[str]) -> int | str:
    stack = []
    for token in tokens:
        if token in ['+', '-', '*', '/']:
            if len(stack) < 2:
                return 'ERROR:INVALID'
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                res = a + b
            elif token == '-':
                res = a - b
            elif token == '*':
                res = a * b
            elif token == '/':
                res = a // b
            stack.append(res)
        else:
            stack.append(int(token))
    if len(stack) != 1:
        return 'ERROR:INVALID'
    if stack[0] == 0:
        return 'ERROR:DIV_BY_ZERO'
    return stack[0] if stack[0] != 0 else 'ERROR:DIV_BY_ZERO'

